export const showcaseS2Code: Record<string, string> = {
  "NavMegaHero": "\"use client\"\n\nimport { ChartLineUp, Cube, Lightning, Plugs, ShieldCheck } from \"@phosphor-icons/react\"\nimport {\n  Button,\n  IconFrame,\n  NavigationMenu,\n  NavigationMenuContent,\n  NavigationMenuItem,\n  NavigationMenuLink,\n  NavigationMenuList,\n  NavigationMenuTrigger,\n  navigationMenuTriggerStyle\n} from \"@glinui/ui\"\n\nconst MEGA = [\n  { icon: ChartLineUp, title: \"Analytics\", text: \"Funnels, cohorts and retention in one view.\" },\n  { icon: Lightning, title: \"Automation\", text: \"Trigger flows from product events.\" },\n  { icon: ShieldCheck, title: \"Access control\", text: \"Roles, SSO and audit logs for every team.\" },\n  { icon: Plugs, title: \"Integrations\", text: \"Sync with the tools your team already uses.\" }\n]\n\nexport function NavMegaHero() {\n  return (\n    <div className=\"mx-auto min-h-80 w-full max-w-3xl\">\n      <header className=\"flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] px-4 py-2.5 [box-shadow:var(--elev-1)]\">\n        <div className=\"flex items-center gap-2 font-semibold\">\n          <IconFrame size=\"sm\" tone=\"accent\"><Cube aria-hidden=\"true\" /></IconFrame>\n          Lumen\n        </div>\n        <NavigationMenu aria-label=\"Main\" defaultValue=\"products\">\n          <NavigationMenuList>\n            <NavigationMenuItem value=\"products\">\n              <NavigationMenuTrigger>Products</NavigationMenuTrigger>\n              <NavigationMenuContent>\n                <div className=\"grid w-full gap-1 p-1 md:w-[34rem] md:grid-cols-2\">\n                  {MEGA.map(({ icon: Icon, title, text }) => (\n                    <NavigationMenuLink key={title} href=\"#\" className=\"flex items-start gap-3\">\n                      <IconFrame size=\"sm\"><Icon aria-hidden=\"true\" /></IconFrame>\n                      <span className=\"grid gap-0.5\">\n                        <span className=\"text-sm font-medium\">{title}</span>\n                        <span className=\"text-xs leading-5 text-[var(--color-muted)]\">{text}</span>\n                      </span>\n                    </NavigationMenuLink>\n                  ))}\n                </div>\n              </NavigationMenuContent>\n            </NavigationMenuItem>\n            <NavigationMenuItem value=\"resources\">\n              <NavigationMenuTrigger>Resources</NavigationMenuTrigger>\n              <NavigationMenuContent>\n                <div className=\"grid w-56 gap-1\">\n                  <NavigationMenuLink href=\"#\">Guides</NavigationMenuLink>\n                  <NavigationMenuLink href=\"#\">Changelog</NavigationMenuLink>\n                </div>\n              </NavigationMenuContent>\n            </NavigationMenuItem>\n            <NavigationMenuItem>\n              <NavigationMenuLink href=\"#\" className={navigationMenuTriggerStyle()}>Pricing</NavigationMenuLink>\n            </NavigationMenuItem>\n          </NavigationMenuList>\n        </NavigationMenu>\n        <div className=\"flex items-center gap-2\">\n          <Button size=\"sm\" variant=\"ghost\">Sign in</Button>\n          <Button size=\"sm\">Start free</Button>\n        </div>\n      </header>\n    </div>\n  )\n}\n",
  "NavInlineExample": "\"use client\"\n\nimport {\n  NavigationMenu,\n  NavigationMenuContent,\n  NavigationMenuItem,\n  NavigationMenuLink,\n  NavigationMenuList,\n  NavigationMenuTrigger,\n  navigationMenuTriggerStyle\n} from \"@glinui/ui\"\n\nexport function NavInlineExample() {\n  return (\n    <div className=\"mx-auto min-h-56 w-full max-w-xl\">\n      <NavigationMenu aria-label=\"Docs\" viewport={false} defaultValue=\"learn\" className=\"max-w-none justify-start\">\n        <NavigationMenuList>\n          <NavigationMenuItem value=\"learn\" className=\"relative\">\n            <NavigationMenuTrigger>Learn</NavigationMenuTrigger>\n            <NavigationMenuContent>\n              <ul className=\"grid w-60 gap-1 p-1\">\n                <li><NavigationMenuLink href=\"#\"><span className=\"block text-sm font-medium\">Quickstart</span><span className=\"block text-xs text-[var(--color-muted)]\">Ship a first page in 5 minutes.</span></NavigationMenuLink></li>\n                <li><NavigationMenuLink href=\"#\"><span className=\"block text-sm font-medium\">Theming</span><span className=\"block text-xs text-[var(--color-muted)]\">Tokens, modes and variants.</span></NavigationMenuLink></li>\n              </ul>\n            </NavigationMenuContent>\n          </NavigationMenuItem>\n          <NavigationMenuItem>\n            <NavigationMenuLink href=\"#\" className={navigationMenuTriggerStyle()}>Components</NavigationMenuLink>\n          </NavigationMenuItem>\n          <NavigationMenuItem>\n            <NavigationMenuLink href=\"#\" className={navigationMenuTriggerStyle()}>Examples</NavigationMenuLink>\n          </NavigationMenuItem>\n        </NavigationMenuList>\n      </NavigationMenu>\n    </div>\n  )\n}\n",
  "MenubarEditorHero": "\"use client\"\n\nimport * as React from \"react\"\nimport {\n  Menubar,\n  MenubarContent,\n  MenubarItem,\n  MenubarMenu,\n  MenubarSeparator,\n  MenubarShortcut,\n  MenubarSub,\n  MenubarSubContent,\n  MenubarSubTrigger,\n  MenubarTrigger\n} from \"@glinui/ui\"\n\nfunction EditorWindow({ open, children }: { open: \"file\" | \"view\"; children: React.ReactNode }) {\n  return (\n    <div className=\"mx-auto min-h-80 w-full max-w-2xl overflow-hidden rounded-xl border border-[var(--line-soft)] bg-[var(--surface-1)] [box-shadow:var(--elev-1)]\">\n      <div className=\"flex items-center gap-3 border-b border-[var(--line-soft)] px-2 py-1.5\">\n        <span className=\"ps-1 text-xs font-semibold\" aria-hidden=\"true\">{`{ }`}</span>\n        <Menubar defaultValue={open} className=\"border-0 bg-transparent p-0 [box-shadow:none]\">\n          {children}\n        </Menubar>\n      </div>\n      <div className=\"grid gap-1 p-4 font-mono text-xs leading-6 text-[var(--color-muted)]\">\n        <p><span className=\"text-[var(--color-accent)]\">export</span> function Header() {\"{\"}</p>\n        <p className=\"ps-4\"><span className=\"text-[var(--color-accent)]\">return</span> {\"<nav aria-label=\\\"Main\\\" />\"}</p>\n        <p>{\"}\"}</p>\n      </div>\n    </div>\n  )\n}\n\nexport function MenubarEditorHero() {\n  return (\n    <EditorWindow open=\"file\">\n      <MenubarMenu value=\"file\">\n        <MenubarTrigger>File</MenubarTrigger>\n        <MenubarContent className=\"w-60\">\n          <MenubarItem>New file <MenubarShortcut>Ctrl N</MenubarShortcut></MenubarItem>\n          <MenubarItem>Open folder <MenubarShortcut>Ctrl O</MenubarShortcut></MenubarItem>\n          <MenubarSub>\n            <MenubarSubTrigger>Open recent</MenubarSubTrigger>\n            <MenubarSubContent>\n              <MenubarItem>lumen-web</MenubarItem>\n              <MenubarItem>billing-service</MenubarItem>\n            </MenubarSubContent>\n          </MenubarSub>\n          <MenubarSeparator />\n          <MenubarItem>Save <MenubarShortcut>Ctrl S</MenubarShortcut></MenubarItem>\n          <MenubarItem>Save all <MenubarShortcut>Ctrl Shift S</MenubarShortcut></MenubarItem>\n          <MenubarSeparator />\n          <MenubarItem>Close editor <MenubarShortcut>Ctrl W</MenubarShortcut></MenubarItem>\n        </MenubarContent>\n      </MenubarMenu>\n      <MenubarMenu value=\"edit\">\n        <MenubarTrigger>Edit</MenubarTrigger>\n        <MenubarContent className=\"w-56\">\n          <MenubarItem>Undo <MenubarShortcut>Ctrl Z</MenubarShortcut></MenubarItem>\n          <MenubarItem>Redo <MenubarShortcut>Ctrl Y</MenubarShortcut></MenubarItem>\n        </MenubarContent>\n      </MenubarMenu>\n      <MenubarMenu value=\"view\">\n        <MenubarTrigger>View</MenubarTrigger>\n        <MenubarContent className=\"w-56\">\n          <MenubarItem>Command palette <MenubarShortcut>Ctrl K</MenubarShortcut></MenubarItem>\n        </MenubarContent>\n      </MenubarMenu>\n    </EditorWindow>\n  )\n}\n",
  "MenubarViewExample": "\"use client\"\n\nimport * as React from \"react\"\nimport {\n  Menubar,\n  MenubarCheckboxItem,\n  MenubarContent,\n  MenubarItem,\n  MenubarLabel,\n  MenubarMenu,\n  MenubarRadioGroup,\n  MenubarRadioItem,\n  MenubarSeparator,\n  MenubarShortcut,\n  MenubarTrigger\n} from \"@glinui/ui\"\n\nfunction EditorWindow({ open, children }: { open: \"file\" | \"view\"; children: React.ReactNode }) {\n  return (\n    <div className=\"mx-auto min-h-80 w-full max-w-2xl overflow-hidden rounded-xl border border-[var(--line-soft)] bg-[var(--surface-1)] [box-shadow:var(--elev-1)]\">\n      <div className=\"flex items-center gap-3 border-b border-[var(--line-soft)] px-2 py-1.5\">\n        <span className=\"ps-1 text-xs font-semibold\" aria-hidden=\"true\">{`{ }`}</span>\n        <Menubar defaultValue={open} className=\"border-0 bg-transparent p-0 [box-shadow:none]\">\n          {children}\n        </Menubar>\n      </div>\n      <div className=\"grid gap-1 p-4 font-mono text-xs leading-6 text-[var(--color-muted)]\">\n        <p><span className=\"text-[var(--color-accent)]\">export</span> function Header() {\"{\"}</p>\n        <p className=\"ps-4\"><span className=\"text-[var(--color-accent)]\">return</span> {\"<nav aria-label=\\\"Main\\\" />\"}</p>\n        <p>{\"}\"}</p>\n      </div>\n    </div>\n  )\n}\n\nexport function MenubarViewExample() {\n  const [minimap, setMinimap] = React.useState(true)\n  const [wrap, setWrap] = React.useState(false)\n  const [theme, setTheme] = React.useState(\"dark\")\n  return (\n    <EditorWindow open=\"view\">\n      <MenubarMenu value=\"file\">\n        <MenubarTrigger>File</MenubarTrigger>\n        <MenubarContent><MenubarItem>New file</MenubarItem></MenubarContent>\n      </MenubarMenu>\n      <MenubarMenu value=\"view\">\n        <MenubarTrigger>View</MenubarTrigger>\n        <MenubarContent className=\"w-60\">\n          <MenubarLabel>Editor</MenubarLabel>\n          <MenubarCheckboxItem checked={minimap} onCheckedChange={setMinimap}>Minimap</MenubarCheckboxItem>\n          <MenubarCheckboxItem checked={wrap} onCheckedChange={setWrap}>Word wrap <MenubarShortcut>Alt Z</MenubarShortcut></MenubarCheckboxItem>\n          <MenubarSeparator />\n          <MenubarLabel>Color theme</MenubarLabel>\n          <MenubarRadioGroup value={theme} onValueChange={setTheme}>\n            <MenubarRadioItem value=\"light\">Light</MenubarRadioItem>\n            <MenubarRadioItem value=\"dark\">Dark</MenubarRadioItem>\n          </MenubarRadioGroup>\n        </MenubarContent>\n      </MenubarMenu>\n    </EditorWindow>\n  )\n}\n",
  "TabsProjectHero": "\"use client\"\n\nimport {\n  Avatar,\n  Badge,\n  Heading,\n  Tabs,\n  TabsContent,\n  TabsList,\n  TabsTrigger,\n  Text\n} from \"@glinui/ui\"\n\nconst ACTIVITY = [\n  { who: \"AK\", text: \"Ava Kim merged release 2.4 into main\", when: \"12 min ago\" },\n  { who: \"JR\", text: \"Jon Reyes commented on the pricing page\", when: \"1 h ago\" },\n  { who: \"SP\", text: \"Sara Patel invited two teammates\", when: \"Yesterday\" }\n]\n\nexport function TabsProjectHero() {\n  return (\n    <div className=\"mx-auto w-full max-w-xl rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\">\n      <div className=\"flex items-center justify-between gap-3\">\n        <div>\n          <Heading level={3} size=\"sm\">Lumen web app</Heading>\n          <Text size=\"sm\" className=\"text-[var(--color-muted)]\">Production, deployed 12 minutes ago</Text>\n        </div>\n        <Badge tone=\"success\" dot>Live</Badge>\n      </div>\n      <Tabs defaultValue=\"activity\" className=\"mt-4\">\n        <TabsList>\n          <TabsTrigger value=\"overview\">Overview</TabsTrigger>\n          <TabsTrigger value=\"activity\">Activity</TabsTrigger>\n          <TabsTrigger value=\"billing\">Billing</TabsTrigger>\n        </TabsList>\n        <TabsContent value=\"overview\">\n          <Text size=\"sm\" className=\"pt-3 text-[var(--color-muted)]\">48.2k visits this week, up 12% on last week.</Text>\n        </TabsContent>\n        <TabsContent value=\"activity\">\n          <ul className=\"grid gap-3 pt-3\">\n            {ACTIVITY.map((row) => (\n              <li key={row.text} className=\"flex items-center gap-3\">\n                <Avatar size=\"sm\" fallback={row.who} alt=\"\" />\n                <span className=\"grid text-sm\">\n                  <span>{row.text}</span>\n                  <span className=\"text-xs text-[var(--color-muted)]\">{row.when}</span>\n                </span>\n              </li>\n            ))}\n          </ul>\n        </TabsContent>\n        <TabsContent value=\"billing\">\n          <Text size=\"sm\" className=\"pt-3 text-[var(--color-muted)]\">Team plan, renews on 1 November. Next invoice: $240.00.</Text>\n        </TabsContent>\n      </Tabs>\n    </div>\n  )\n}\n",
  "TabsUnderlineExample": "\"use client\"\n\nimport { Receipt, ShieldCheck, UsersThree } from \"@phosphor-icons/react\"\nimport {\n  Badge,\n  Tabs,\n  TabsContent,\n  TabsList,\n  TabsTrigger,\n  Text\n} from \"@glinui/ui\"\n\nexport function TabsUnderlineExample() {\n  return (\n    <div className=\"mx-auto w-full max-w-xl\">\n      <Tabs defaultValue=\"members\">\n        <TabsList variant=\"underline\" className=\"w-full justify-start overflow-x-auto\">\n          <TabsTrigger value=\"members\" className=\"gap-1.5\"><UsersThree aria-hidden=\"true\" />Members</TabsTrigger>\n          <TabsTrigger value=\"roles\" className=\"gap-1.5\"><ShieldCheck aria-hidden=\"true\" />Roles</TabsTrigger>\n          <TabsTrigger value=\"invoices\" className=\"gap-1.5\"><Receipt aria-hidden=\"true\" />Invoices <Badge size=\"sm\">3</Badge></TabsTrigger>\n          <TabsTrigger value=\"locked\" disabled>Audit log</TabsTrigger>\n        </TabsList>\n        <TabsContent value=\"members\"><Text size=\"sm\" className=\"pt-4 text-[var(--color-muted)]\">12 members across 3 teams.</Text></TabsContent>\n        <TabsContent value=\"roles\"><Text size=\"sm\" className=\"pt-4 text-[var(--color-muted)]\">Owner, admin, editor and viewer roles.</Text></TabsContent>\n        <TabsContent value=\"invoices\"><Text size=\"sm\" className=\"pt-4 text-[var(--color-muted)]\">3 invoices are waiting for payment.</Text></TabsContent>\n      </Tabs>\n    </div>\n  )\n}\n",
  "BreadcrumbHeaderHero": "\"use client\"\n\nimport { House } from \"@phosphor-icons/react\"\nimport {\n  Breadcrumb,\n  BreadcrumbEllipsis,\n  BreadcrumbItem,\n  BreadcrumbLink,\n  BreadcrumbList,\n  BreadcrumbPage,\n  BreadcrumbSeparator,\n  Button,\n  Heading,\n  Text\n} from \"@glinui/ui\"\n\nexport function BreadcrumbHeaderHero() {\n  return (\n    <div className=\"mx-auto w-full max-w-2xl rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\">\n      <Breadcrumb>\n        <BreadcrumbList>\n          <BreadcrumbItem><BreadcrumbLink href=\"#\"><House aria-hidden=\"true\" className=\"size-4\" /><span className=\"sr-only\">Home</span></BreadcrumbLink></BreadcrumbItem>\n          <BreadcrumbSeparator />\n          <BreadcrumbItem><BreadcrumbEllipsis /></BreadcrumbItem>\n          <BreadcrumbSeparator />\n          <BreadcrumbItem><BreadcrumbLink href=\"#\">Projects</BreadcrumbLink></BreadcrumbItem>\n          <BreadcrumbSeparator />\n          <BreadcrumbItem><BreadcrumbLink href=\"#\">Lumen web</BreadcrumbLink></BreadcrumbItem>\n          <BreadcrumbSeparator />\n          <BreadcrumbItem><BreadcrumbPage>Deployments</BreadcrumbPage></BreadcrumbItem>\n        </BreadcrumbList>\n      </Breadcrumb>\n      <div className=\"mt-4 flex flex-wrap items-center justify-between gap-3\">\n        <div>\n          <Heading level={3} size=\"md\">Deployments</Heading>\n          <Text size=\"sm\" className=\"text-[var(--color-muted)]\">Every build of Lumen web, newest first.</Text>\n        </div>\n        <Button size=\"sm\">New deployment</Button>\n      </div>\n    </div>\n  )\n}\n",
  "BreadcrumbFilesExample": "\"use client\"\n\nimport { FileText } from \"@phosphor-icons/react\"\nimport {\n  Breadcrumb,\n  BreadcrumbItem,\n  BreadcrumbLink,\n  BreadcrumbList,\n  BreadcrumbPage,\n  BreadcrumbSeparator\n} from \"@glinui/ui\"\n\nexport function BreadcrumbFilesExample() {\n  return (\n    <div className=\"mx-auto grid w-full max-w-xl gap-4\">\n      <Breadcrumb>\n        <BreadcrumbList>\n          <BreadcrumbItem><BreadcrumbLink href=\"#\">Documents</BreadcrumbLink></BreadcrumbItem>\n          <BreadcrumbSeparator>/</BreadcrumbSeparator>\n          <BreadcrumbItem><BreadcrumbLink href=\"#\">Contracts</BreadcrumbLink></BreadcrumbItem>\n          <BreadcrumbSeparator>/</BreadcrumbSeparator>\n          <BreadcrumbItem><BreadcrumbPage><FileText aria-hidden=\"true\" className=\"me-1 inline size-4\" />Vendor agreement.pdf</BreadcrumbPage></BreadcrumbItem>\n        </BreadcrumbList>\n      </Breadcrumb>\n      <Breadcrumb>\n        <BreadcrumbList>\n          <BreadcrumbItem><BreadcrumbLink href=\"#\">Settings</BreadcrumbLink></BreadcrumbItem>\n          <BreadcrumbSeparator />\n          <BreadcrumbItem><BreadcrumbPage>Billing</BreadcrumbPage></BreadcrumbItem>\n        </BreadcrumbList>\n      </Breadcrumb>\n    </div>\n  )\n}\n",
  "PaginationTableHero": "\"use client\"\n\nimport {\n  Badge,\n  Pagination,\n  PaginationContent,\n  PaginationEllipsis,\n  PaginationItem,\n  PaginationLink,\n  PaginationNext,\n  PaginationPrevious,\n  Table,\n  TableBody,\n  TableCell,\n  TableHead,\n  TableHeader,\n  TableRow,\n  Text\n} from \"@glinui/ui\"\n\nconst INVOICES = [\n  { id: \"INV-1042\", customer: \"Northwind Traders\", amount: \"$1,280.00\", status: \"Paid\", tone: \"success\" },\n  { id: \"INV-1041\", customer: \"Halcyon Labs\", amount: \"$640.00\", status: \"Pending\", tone: \"warning\" },\n  { id: \"INV-1040\", customer: \"Brightside Co\", amount: \"$2,150.00\", status: \"Paid\", tone: \"success\" },\n  { id: \"INV-1039\", customer: \"Orbit Studio\", amount: \"$320.00\", status: \"Overdue\", tone: \"danger\" }\n] as const\n\nexport function PaginationTableHero() {\n  return (\n    <div className=\"mx-auto w-full max-w-2xl rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-4 [box-shadow:var(--elev-1)]\">\n      <div className=\"overflow-x-auto\">\n        <Table>\n          <TableHeader>\n            <TableRow>\n              <TableHead>Invoice</TableHead>\n              <TableHead>Customer</TableHead>\n              <TableHead>Status</TableHead>\n              <TableHead className=\"text-end\">Amount</TableHead>\n            </TableRow>\n          </TableHeader>\n          <TableBody>\n            {INVOICES.map((row) => (\n              <TableRow key={row.id}>\n                <TableCell className=\"font-medium\">{row.id}</TableCell>\n                <TableCell>{row.customer}</TableCell>\n                <TableCell><Badge size=\"sm\" tone={row.tone} dot>{row.status}</Badge></TableCell>\n                <TableCell className=\"text-end tabular-nums\">{row.amount}</TableCell>\n              </TableRow>\n            ))}\n          </TableBody>\n        </Table>\n      </div>\n      <div className=\"mt-4 flex flex-wrap items-center justify-between gap-3\">\n        <Text size=\"sm\" className=\"text-[var(--color-muted)]\">Showing 1 to 4 of 48 invoices</Text>\n        <Pagination className=\"mx-0 w-auto\">\n          <PaginationContent>\n            <PaginationItem><PaginationPrevious href=\"#\" /></PaginationItem>\n            <PaginationItem><PaginationLink href=\"#\" isActive>1</PaginationLink></PaginationItem>\n            <PaginationItem><PaginationLink href=\"#\">2</PaginationLink></PaginationItem>\n            <PaginationItem><PaginationLink href=\"#\">3</PaginationLink></PaginationItem>\n            <PaginationItem><PaginationEllipsis /></PaginationItem>\n            <PaginationItem><PaginationLink href=\"#\">12</PaginationLink></PaginationItem>\n            <PaginationItem><PaginationNext href=\"#\" /></PaginationItem>\n          </PaginationContent>\n        </Pagination>\n      </div>\n    </div>\n  )\n}\n",
  "PaginationCompactExample": "\"use client\"\n\nimport {\n  Pagination,\n  PaginationContent,\n  PaginationItem,\n  PaginationLink,\n  PaginationNext,\n  PaginationPrevious\n} from \"@glinui/ui\"\n\nexport function PaginationCompactExample() {\n  return (\n    <div className=\"mx-auto grid w-full max-w-md gap-6\">\n      <Pagination>\n        <PaginationContent>\n          <PaginationItem><PaginationPrevious href=\"#\" /></PaginationItem>\n          <PaginationItem><PaginationLink href=\"#\" isActive>4</PaginationLink></PaginationItem>\n          <PaginationItem><PaginationNext href=\"#\" /></PaginationItem>\n        </PaginationContent>\n      </Pagination>\n      <Pagination>\n        <PaginationContent>\n          <PaginationItem><PaginationLink href=\"#\" aria-label=\"Page 1\">1</PaginationLink></PaginationItem>\n          <PaginationItem><PaginationLink href=\"#\" isActive aria-label=\"Page 2\">2</PaginationLink></PaginationItem>\n          <PaginationItem><PaginationLink href=\"#\" aria-label=\"Page 3\">3</PaginationLink></PaginationItem>\n        </PaginationContent>\n      </Pagination>\n    </div>\n  )\n}\n",
  "SidebarShellHero": "\"use client\"\n\nimport { ChartLineUp, Cube, GearSix, House, Receipt, SidebarSimple, Stack, Users } from \"@phosphor-icons/react\"\nimport {\n  Avatar,\n  Checkbox,\n  Heading,\n  IconFrame,\n  Kbd,\n  Sidebar,\n  SidebarContent,\n  SidebarFooter,\n  SidebarGroup,\n  SidebarGroupContent,\n  SidebarGroupLabel,\n  SidebarHeader,\n  SidebarInset,\n  SidebarMenu,\n  SidebarMenuBadge,\n  SidebarMenuButton,\n  SidebarMenuItem,\n  SidebarProvider,\n  SidebarTrigger,\n  Text\n} from \"@glinui/ui\"\n\nconst NAV_MAIN = [\n  { icon: House, label: \"Overview\", active: true },\n  { icon: ChartLineUp, label: \"Analytics\" },\n  { icon: Stack, label: \"Projects\", badge: \"8\" },\n  { icon: Users, label: \"Team\" }\n]\n\nconst NAV_ADMIN = [\n  { icon: Receipt, label: \"Billing\" },\n  { icon: GearSix, label: \"Settings\" }\n]\n\nexport function SidebarShellHero() {\n  return (\n    <SidebarProvider storageKey={null} className=\"mx-auto h-96 min-h-0 w-full max-w-3xl overflow-hidden rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] [box-shadow:var(--elev-1)]\">\n      <Sidebar collapsible=\"icon\" label=\"App\" containerClassName=\"static h-full\">\n        <SidebarHeader>\n          <SidebarMenu>\n            <SidebarMenuItem>\n              <SidebarMenuButton size=\"lg\" tooltip=\"Lumen\">\n                <IconFrame size=\"sm\" tone=\"accent\"><Cube aria-hidden=\"true\" /></IconFrame>\n                <span className=\"grid text-start leading-tight\"><span className=\"text-sm font-semibold\">Lumen</span><span className=\"text-xs text-[var(--color-muted)]\">Team plan</span></span>\n              </SidebarMenuButton>\n            </SidebarMenuItem>\n          </SidebarMenu>\n        </SidebarHeader>\n        <SidebarContent>\n          <SidebarGroup>\n            <SidebarGroupLabel>Workspace</SidebarGroupLabel>\n            <SidebarGroupContent>\n              <SidebarMenu>\n                {NAV_MAIN.map(({ icon: Icon, label, active, badge }) => (\n                  <SidebarMenuItem key={label}>\n                    <SidebarMenuButton isActive={active} tooltip={label}><Icon aria-hidden=\"true\" /><span>{label}</span></SidebarMenuButton>\n                    {badge ? <SidebarMenuBadge>{badge}</SidebarMenuBadge> : null}\n                  </SidebarMenuItem>\n                ))}\n              </SidebarMenu>\n            </SidebarGroupContent>\n          </SidebarGroup>\n          <SidebarGroup collapsible>\n            <SidebarGroupLabel>Admin</SidebarGroupLabel>\n            <SidebarGroupContent>\n              <SidebarMenu>\n                {NAV_ADMIN.map(({ icon: Icon, label }) => (\n                  <SidebarMenuItem key={label}>\n                    <SidebarMenuButton tooltip={label}><Icon aria-hidden=\"true\" /><span>{label}</span></SidebarMenuButton>\n                  </SidebarMenuItem>\n                ))}\n              </SidebarMenu>\n            </SidebarGroupContent>\n          </SidebarGroup>\n        </SidebarContent>\n        <SidebarFooter>\n          <SidebarMenu>\n            <SidebarMenuItem>\n              <SidebarMenuButton size=\"lg\" tooltip=\"Ava Kim\">\n                <Avatar size=\"sm\" fallback=\"AK\" alt=\"\" />\n                <span className=\"grid text-start leading-tight\"><span className=\"text-sm font-medium\">Ava Kim</span><span className=\"text-xs text-[var(--color-muted)]\">ava@lumen.test</span></span>\n              </SidebarMenuButton>\n            </SidebarMenuItem>\n          </SidebarMenu>\n        </SidebarFooter>\n      </Sidebar>\n      <SidebarInset className=\"min-w-0 flex-1 p-4\">\n        <div className=\"flex items-center gap-2\">\n          <SidebarTrigger aria-label=\"Toggle sidebar\"><SidebarSimple aria-hidden=\"true\" /></SidebarTrigger>\n          <Heading level={3} size=\"sm\">Overview</Heading>\n          <Kbd className=\"ms-auto\">Ctrl B</Kbd>\n        </div>\n        <div className=\"mt-4 grid gap-3 sm:grid-cols-2\">\n          {[{ k: \"Visits\", v: \"48.2k\" }, { k: \"Conversion\", v: \"3.9%\" }].map((m) => (\n            <div key={m.k} className=\"rounded-xl border border-[var(--line-soft)] p-3\">\n              <Text size=\"sm\" className=\"text-[var(--color-muted)]\">{m.k}</Text>\n              <p className=\"text-2xl font-semibold tabular-nums\">{m.v}</p>\n            </div>\n          ))}\n        </div>\n        <label className=\"mt-4 flex items-center gap-2 text-sm\"><Checkbox defaultChecked /> Show weekly digest</label>\n      </SidebarInset>\n    </SidebarProvider>\n  )\n}\n",
  "LinkChangelogHero": "\"use client\"\n\nimport {\n  Badge,\n  Heading,\n  Link,\n  Text\n} from \"@glinui/ui\"\n\nexport function LinkChangelogHero() {\n  return (\n    <div className=\"mx-auto w-full max-w-md rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\">\n      <div className=\"flex items-center gap-2\">\n        <Badge tone=\"accent\" size=\"sm\">v2.4</Badge>\n        <Text size=\"sm\" className=\"text-[var(--color-muted)]\">Released 3 October</Text>\n      </div>\n      <Heading level={3} size=\"md\" className=\"mt-3\">Faster dashboards</Heading>\n      <Text className=\"mt-2 text-[var(--color-muted)]\">\n        Charts now render from cached queries, so the overview loads in under a second. Read the{\" \"}\n        <Link href=\"#\">migration notes</Link> before upgrading, or check the <Link href=\"#\" underline={false}>full changelog</Link>.\n      </Text>\n      <div className=\"mt-4 flex flex-wrap items-center gap-4\">\n        <Link href=\"#\" variant=\"arrow\">Read the release post</Link>\n        <Link href=\"#\" variant=\"ghost\">Download notes</Link>\n      </div>\n      <nav aria-label=\"Footer\" className=\"mt-5 flex flex-wrap gap-x-4 gap-y-1 border-t border-[var(--line-soft)] pt-3 text-sm\">\n        <Link href=\"#\" variant=\"ghost\" size=\"sm\">Status</Link>\n        <Link href=\"#\" variant=\"ghost\" size=\"sm\">Privacy</Link>\n        <Link href=\"#\" variant=\"ghost\" size=\"sm\">Terms</Link>\n      </nav>\n    </div>\n  )\n}\n",
  "LinkStatesExample": "\"use client\"\n\nimport {\n  Link\n} from \"@glinui/ui\"\n\nexport function LinkStatesExample() {\n  return (\n    <div className=\"mx-auto grid w-full max-w-md gap-3\">\n      <Link href=\"#\">Default underlined link</Link>\n      <Link href=\"#\" underline={false}>Link without underline</Link>\n      <Link href=\"#\" variant=\"arrow\">Arrow link</Link>\n      <Link href=\"#\" variant=\"outline\">Outline link</Link>\n      <Link href=\"#\" size=\"lg\">Large link</Link>\n    </div>\n  )\n}\n",
  "ModalInviteHero": "\"use client\"\n\nimport * as React from \"react\"\nimport { UserPlus } from \"@phosphor-icons/react\"\nimport {\n  Avatar,\n  Badge,\n  Button,\n  Heading,\n  Input,\n  Label,\n  Modal,\n  ModalClose,\n  ModalContent,\n  ModalDescription,\n  ModalFooter,\n  ModalHeader,\n  ModalTitle,\n  ModalTrigger,\n  Text\n} from \"@glinui/ui\"\n\nconst CARD = \"mx-auto w-full rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\"\n\nconst MEMBERS = [\n  { name: \"Ava Kim\", mail: \"ava@lumen.test\", role: \"Owner\", initials: \"AK\" },\n  { name: \"Jon Reyes\", mail: \"jon@lumen.test\", role: \"Admin\", initials: \"JR\" },\n  { name: \"Sara Patel\", mail: \"sara@lumen.test\", role: \"Editor\", initials: \"SP\" }\n]\n\nexport function ModalInviteHero() {\n  const [emails, setEmails] = React.useState<string[]>([\"mia@lumen.test\"])\n  const [draft, setDraft] = React.useState(\"\")\n  const add = () => {\n    const value = draft.trim()\n    if (value && !emails.includes(value)) setEmails([...emails, value])\n    setDraft(\"\")\n  }\n  return (\n    <div className={`${CARD} max-w-lg`}>\n      <div className=\"flex items-center justify-between gap-3\">\n        <div>\n          <Heading level={3} size=\"sm\">Members</Heading>\n          <Text size=\"sm\" className=\"text-[var(--color-muted)]\">3 of 10 seats used</Text>\n        </div>\n        <Modal>\n          <ModalTrigger asChild><Button size=\"sm\"><UserPlus aria-hidden=\"true\" />Invite teammates</Button></ModalTrigger>\n          <ModalContent>\n            <ModalHeader>\n              <ModalTitle>Invite teammates</ModalTitle>\n              <ModalDescription>They get an email with a link to join Lumen.</ModalDescription>\n            </ModalHeader>\n            <form\n              className=\"grid gap-3\"\n              onSubmit={(event) => {\n                event.preventDefault()\n                add()\n              }}\n            >\n              <Label htmlFor=\"invite-email\">Email address</Label>\n              <div className=\"flex gap-2\">\n                <Input id=\"invite-email\" type=\"email\" placeholder=\"name@company.com\" value={draft} onChange={(event) => setDraft(event.target.value)} />\n                <Button type=\"submit\" variant=\"outline\">Add</Button>\n              </div>\n            </form>\n            <ul className=\"grid gap-2\" aria-label=\"People to invite\">\n              {emails.map((email) => (\n                <li key={email} className=\"flex items-center justify-between gap-3 text-sm\">\n                  <span className=\"flex items-center gap-2\"><Avatar size=\"xs\" fallback={email.slice(0, 2).toUpperCase()} alt=\"\" />{email}</span>\n                  <Badge size=\"sm\">Editor</Badge>\n                </li>\n              ))}\n            </ul>\n            <ModalFooter>\n              <ModalClose asChild><Button variant=\"ghost\">Cancel</Button></ModalClose>\n              <ModalClose asChild><Button disabled={emails.length === 0}>{`Send ${emails.length} invite${emails.length === 1 ? \"\" : \"s\"}`}</Button></ModalClose>\n            </ModalFooter>\n          </ModalContent>\n        </Modal>\n      </div>\n      <ul className=\"mt-4 grid divide-y divide-[var(--line-soft)]\">\n        {MEMBERS.map((member) => (\n          <li key={member.mail} className=\"flex items-center gap-3 py-2.5\">\n            <Avatar size=\"sm\" fallback={member.initials} alt=\"\" />\n            <span className=\"grid min-w-0 flex-1 text-sm\">\n              <span className=\"font-medium\">{member.name}</span>\n              <span className=\"truncate text-xs text-[var(--color-muted)]\">{member.mail}</span>\n            </span>\n            <Badge size=\"sm\">{member.role}</Badge>\n          </li>\n        ))}\n      </ul>\n    </div>\n  )\n}\n",
  "ModalSizesExample": "\"use client\"\n\nimport {\n  Button,\n  Input,\n  Modal,\n  ModalClose,\n  ModalContent,\n  ModalDescription,\n  ModalFooter,\n  ModalHeader,\n  ModalTitle,\n  ModalTrigger\n} from \"@glinui/ui\"\n\nexport function ModalSizesExample() {\n  return (\n    <div className=\"mx-auto flex flex-wrap items-center justify-center gap-3\">\n      {([\"sm\", \"md\", \"lg\"] as const).map((size) => (\n        <Modal key={size}>\n          <ModalTrigger asChild><Button variant=\"outline\" size=\"sm\">{`Size ${size}`}</Button></ModalTrigger>\n          <ModalContent size={size}>\n            <ModalHeader>\n              <ModalTitle>Rename workspace</ModalTitle>\n              <ModalDescription>Pick a name your team will recognise.</ModalDescription>\n            </ModalHeader>\n            <Input aria-label=\"Workspace name\" defaultValue=\"Lumen\" />\n            <ModalFooter>\n              <ModalClose asChild><Button variant=\"ghost\">Cancel</Button></ModalClose>\n              <ModalClose asChild><Button>Save name</Button></ModalClose>\n            </ModalFooter>\n          </ModalContent>\n        </Modal>\n      ))}\n    </div>\n  )\n}\n",
  "AlertDeleteHero": "\"use client\"\n\nimport * as React from \"react\"\nimport { Trash } from \"@phosphor-icons/react\"\nimport {\n  AlertDialog,\n  AlertDialogAction,\n  AlertDialogCancel,\n  AlertDialogContent,\n  AlertDialogDescription,\n  AlertDialogFooter,\n  AlertDialogHeader,\n  AlertDialogTitle,\n  AlertDialogTrigger,\n  Button,\n  Heading,\n  IconFrame,\n  Input,\n  Label,\n  Text\n} from \"@glinui/ui\"\n\nconst CARD = \"mx-auto w-full rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\"\n\nexport function AlertDeleteHero() {\n  const [confirm, setConfirm] = React.useState(\"\")\n  return (\n    <div className={`${CARD} max-w-lg`}>\n      <div className=\"flex items-start gap-3\">\n        <IconFrame tone=\"danger\"><Trash aria-hidden=\"true\" /></IconFrame>\n        <div className=\"grid flex-1 gap-1\">\n          <Heading level={3} size=\"sm\">Delete this project</Heading>\n          <Text size=\"sm\" className=\"text-[var(--color-muted)]\">Removes lumen-web, its deployments and all stored analytics.</Text>\n        </div>\n      </div>\n      <div className=\"mt-4 flex justify-end\">\n        <AlertDialog onOpenChange={() => setConfirm(\"\")}>\n          <AlertDialogTrigger asChild><Button variant=\"outline\" tone=\"danger\">Delete project</Button></AlertDialogTrigger>\n          <AlertDialogContent>\n            <AlertDialogHeader>\n              <AlertDialogTitle>Delete lumen-web?</AlertDialogTitle>\n              <AlertDialogDescription>This cannot be undone. Deleting the project will:</AlertDialogDescription>\n            </AlertDialogHeader>\n            <ul className=\"list-disc space-y-1 ps-5 text-sm text-[var(--color-muted)]\">\n              <li>Remove 142 deployments and their logs</li>\n              <li>Disconnect 3 custom domains</li>\n              <li>Cancel the 2 scheduled jobs</li>\n            </ul>\n            <div className=\"grid gap-2\">\n              <Label htmlFor=\"confirm-name\">Type lumen-web to confirm</Label>\n              <Input id=\"confirm-name\" value={confirm} onChange={(event) => setConfirm(event.target.value)} autoComplete=\"off\" />\n            </div>\n            <AlertDialogFooter>\n              <AlertDialogCancel>Keep project</AlertDialogCancel>\n              <AlertDialogAction variant=\"destructive\" disabled={confirm !== \"lumen-web\"}>Delete project</AlertDialogAction>\n            </AlertDialogFooter>\n          </AlertDialogContent>\n        </AlertDialog>\n      </div>\n    </div>\n  )\n}\n",
  "AlertDiscardExample": "\"use client\"\n\nimport {\n  AlertDialog,\n  AlertDialogAction,\n  AlertDialogCancel,\n  AlertDialogContent,\n  AlertDialogDescription,\n  AlertDialogFooter,\n  AlertDialogHeader,\n  AlertDialogTitle,\n  AlertDialogTrigger,\n  Button,\n  Input,\n  Label\n} from \"@glinui/ui\"\n\nconst CARD = \"mx-auto w-full rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\"\n\nexport function AlertDiscardExample() {\n  return (\n    <div className={`${CARD} max-w-md`}>\n      <Label htmlFor=\"draft-title\">Post title</Label>\n      <Input id=\"draft-title\" className=\"mt-2\" defaultValue=\"Launch notes for v2.4\" />\n      <div className=\"mt-4 flex justify-end gap-2\">\n        <AlertDialog>\n          <AlertDialogTrigger asChild><Button variant=\"ghost\">Discard draft</Button></AlertDialogTrigger>\n          <AlertDialogContent size=\"sm\">\n            <AlertDialogHeader>\n              <AlertDialogTitle>Discard this draft?</AlertDialogTitle>\n              <AlertDialogDescription>Your unsaved edits will be lost.</AlertDialogDescription>\n            </AlertDialogHeader>\n            <AlertDialogFooter>\n              <AlertDialogCancel>Keep editing</AlertDialogCancel>\n              <AlertDialogAction>Discard</AlertDialogAction>\n            </AlertDialogFooter>\n          </AlertDialogContent>\n        </AlertDialog>\n        <Button>Publish</Button>\n      </div>\n    </div>\n  )\n}\n",
  "SheetFiltersHero": "\"use client\"\n\nimport { Funnel } from \"@phosphor-icons/react\"\nimport {\n  Badge,\n  Button,\n  Checkbox,\n  Heading,\n  Label,\n  Sheet,\n  SheetClose,\n  SheetContent,\n  SheetDescription,\n  SheetFooter,\n  SheetHeader,\n  SheetTitle,\n  SheetTrigger,\n  Switch\n} from \"@glinui/ui\"\n\nconst CARD = \"mx-auto w-full rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\"\n\nconst LISTINGS = [\n  { name: \"Harbor loft\", meta: \"2 bed, 1 bath\", price: \"$2,400\" },\n  { name: \"Maple row house\", meta: \"3 bed, 2 bath\", price: \"$3,150\" },\n  { name: \"Station studio\", meta: \"Studio, 1 bath\", price: \"$1,350\" }\n]\n\nexport function SheetFiltersHero() {\n  return (\n    <div className={`${CARD} max-w-lg`}>\n      <div className=\"flex items-center justify-between gap-3\">\n        <Heading level={3} size=\"sm\">Rentals near you</Heading>\n        <Sheet>\n          <SheetTrigger asChild><Button size=\"sm\" variant=\"outline\"><Funnel aria-hidden=\"true\" />Filters<Badge size=\"sm\" className=\"ms-1\">2</Badge></Button></SheetTrigger>\n          <SheetContent side=\"right\">\n            <SheetHeader>\n              <SheetTitle>Filters</SheetTitle>\n              <SheetDescription>Narrow 128 listings by what matters.</SheetDescription>\n            </SheetHeader>\n            <fieldset className=\"grid gap-3 py-4\">\n              <legend className=\"mb-1 text-sm font-medium\">Bedrooms</legend>\n              {[\"Studio\", \"1 bedroom\", \"2 bedrooms\", \"3 or more\"].map((label, index) => (\n                <label key={label} className=\"flex items-center gap-2 text-sm\"><Checkbox defaultChecked={index === 2} />{label}</label>\n              ))}\n            </fieldset>\n            <div className=\"flex items-center justify-between gap-3 border-t border-[var(--line-soft)] py-3 text-sm\">\n              <Label htmlFor=\"pets\">Pets allowed</Label>\n              <Switch id=\"pets\" defaultChecked />\n            </div>\n            <SheetFooter>\n              <SheetClose asChild><Button variant=\"ghost\">Reset</Button></SheetClose>\n              <SheetClose asChild><Button>Show 41 results</Button></SheetClose>\n            </SheetFooter>\n          </SheetContent>\n        </Sheet>\n      </div>\n      <ul className=\"mt-4 grid divide-y divide-[var(--line-soft)]\">\n        {LISTINGS.map((item) => (\n          <li key={item.name} className=\"flex items-center justify-between gap-3 py-3 text-sm\">\n            <span className=\"grid\"><span className=\"font-medium\">{item.name}</span><span className=\"text-xs text-[var(--color-muted)]\">{item.meta}</span></span>\n            <span className=\"tabular-nums\">{item.price}</span>\n          </li>\n        ))}\n      </ul>\n    </div>\n  )\n}\n",
  "SheetMobileNavExample": "\"use client\"\n\nimport { FolderSimple, GearSix, House, List, Users } from \"@phosphor-icons/react\"\nimport {\n  Button,\n  Sheet,\n  SheetContent,\n  SheetDescription,\n  SheetHeader,\n  SheetTitle,\n  SheetTrigger,\n  Text\n} from \"@glinui/ui\"\n\nexport function SheetMobileNavExample() {\n  const links = [\n    { icon: House, label: \"Home\" },\n    { icon: FolderSimple, label: \"Projects\" },\n    { icon: Users, label: \"Team\" },\n    { icon: GearSix, label: \"Settings\" }\n  ]\n  return (\n    <div className=\"mx-auto w-full max-w-sm rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] [box-shadow:var(--elev-1)]\">\n      <div className=\"flex items-center gap-2 border-b border-[var(--line-soft)] px-3 py-2\">\n        <Sheet>\n          <SheetTrigger asChild><Button size=\"icon\" variant=\"ghost\" aria-label=\"Open menu\"><List aria-hidden=\"true\" /></Button></SheetTrigger>\n          <SheetContent side=\"left\">\n            <SheetHeader>\n              <SheetTitle>Lumen</SheetTitle>\n              <SheetDescription>Jump to a section.</SheetDescription>\n            </SheetHeader>\n            <nav aria-label=\"Mobile\" className=\"grid gap-1 py-4\">\n              {links.map(({ icon: Icon, label }) => (\n                <a key={label} href=\"#\" className=\"flex items-center gap-3 rounded-lg px-3 py-2 text-sm hover:bg-[color-mix(in_oklab,var(--color-foreground)_8%,transparent)]\"><Icon aria-hidden=\"true\" className=\"size-4\" />{label}</a>\n              ))}\n            </nav>\n          </SheetContent>\n        </Sheet>\n        <span className=\"text-sm font-semibold\">Lumen</span>\n      </div>\n      <div className=\"p-4\"><Text size=\"sm\" className=\"text-[var(--color-muted)]\">Tap the menu to slide the navigation in from the left.</Text></div>\n    </div>\n  )\n}\n",
  "PopoverShareHero": "\"use client\"\n\nimport { Copy, FileText, Link as LinkIcon } from \"@phosphor-icons/react\"\nimport {\n  Button,\n  Input,\n  Label,\n  Popover,\n  PopoverContent,\n  PopoverTrigger,\n  Switch\n} from \"@glinui/ui\"\n\nconst CARD = \"mx-auto w-full rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\"\n\nexport function PopoverShareHero() {\n  return (\n    <div className=\"mx-auto flex min-h-72 w-full max-w-md flex-col items-end\">\n      <div className={`${CARD} flex items-center justify-between gap-3`}>\n        <span className=\"flex items-center gap-2 text-sm font-medium\"><FileText aria-hidden=\"true\" className=\"size-4\" />Q4 roadmap</span>\n        <Popover defaultOpen>\n          <PopoverTrigger asChild><Button size=\"sm\"><LinkIcon aria-hidden=\"true\" />Share</Button></PopoverTrigger>\n          <PopoverContent align=\"end\" className=\"w-80\" onOpenAutoFocus={(event) => event.preventDefault()}>\n            <div className=\"grid gap-3\">\n              <div>\n                <p className=\"text-sm font-medium\">Share this document</p>\n                <p className=\"text-xs text-[var(--color-muted)]\">Anyone with the link can view.</p>\n              </div>\n              <div className=\"flex gap-2\">\n                <Input aria-label=\"Share link\" readOnly value=\"lumen.test/d/q4-roadmap\" />\n                <Button size=\"icon\" variant=\"outline\" aria-label=\"Copy link\"><Copy aria-hidden=\"true\" /></Button>\n              </div>\n              <div className=\"flex items-center justify-between text-sm\">\n                <Label htmlFor=\"allow-comments\">Allow comments</Label>\n                <Switch id=\"allow-comments\" defaultChecked />\n              </div>\n            </div>\n          </PopoverContent>\n        </Popover>\n      </div>\n    </div>\n  )\n}\n",
  "PopoverNotificationsExample": "\"use client\"\n\nimport { Bell } from \"@phosphor-icons/react\"\nimport {\n  Button,\n  Popover,\n  PopoverContent,\n  PopoverTrigger\n} from \"@glinui/ui\"\n\nexport function PopoverNotificationsExample() {\n  const items = [\n    { title: \"Deploy finished\", when: \"2 min ago\" },\n    { title: \"Sara commented on Pricing\", when: \"1 h ago\" },\n    { title: \"Invoice INV-1042 paid\", when: \"Yesterday\" }\n  ]\n  return (\n    <div className=\"mx-auto flex w-full max-w-xs justify-center\">\n      <Popover>\n        <PopoverTrigger asChild><Button variant=\"outline\" size=\"icon\" aria-label=\"Notifications, 3 new\"><Bell aria-hidden=\"true\" /></Button></PopoverTrigger>\n        <PopoverContent className=\"w-72\">\n          <p className=\"text-sm font-medium\">Notifications</p>\n          <ul className=\"mt-2 grid divide-y divide-[var(--line-soft)]\">\n            {items.map((item) => (\n              <li key={item.title} className=\"py-2 text-sm\"><p>{item.title}</p><p className=\"text-xs text-[var(--color-muted)]\">{item.when}</p></li>\n            ))}\n          </ul>\n        </PopoverContent>\n      </Popover>\n    </div>\n  )\n}\n",
  "HoverCardProfileHero": "\"use client\"\n\nimport {\n  Avatar,\n  HoverCard,\n  HoverCardContent,\n  HoverCardTrigger\n} from \"@glinui/ui\"\n\nconst CARD = \"mx-auto w-full rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\"\n\nexport function HoverCardProfileHero() {\n  return (\n    <div className={`${CARD} max-w-md`}>\n      <p className=\"text-sm leading-6\">\n        Release notes drafted by{\" \"}\n        <HoverCard defaultOpen openDelay={100}>\n          <HoverCardTrigger asChild>\n            <a href=\"#\" className=\"font-medium text-[var(--color-accent)] underline decoration-dotted underline-offset-4\">@avakim</a>\n          </HoverCardTrigger>\n          <HoverCardContent className=\"w-80\">\n            <div className=\"flex gap-3\">\n              <Avatar size=\"lg\" fallback=\"AK\" alt=\"Ava Kim\" />\n              <div className=\"grid gap-1\">\n                <p className=\"text-sm font-semibold\">Ava Kim</p>\n                <p className=\"text-xs text-[var(--color-muted)]\">@avakim</p>\n                <p className=\"text-sm\">Design engineer on the platform team. Writes about tokens and motion.</p>\n                <div className=\"mt-1 flex items-center gap-3 text-xs text-[var(--color-muted)]\">\n                  <span><strong className=\"text-[var(--color-foreground)]\">128</strong> posts</span>\n                  <span><strong className=\"text-[var(--color-foreground)]\">2.4k</strong> followers</span>\n                </div>\n              </div>\n            </div>\n          </HoverCardContent>\n        </HoverCard>\n        {\" \"}and reviewed by the docs team. Hover the handle to see who wrote it.\n      </p>\n    </div>\n  )\n}\n",
  "HoverCardLinkExample": "\"use client\"\n\nimport {\n  HoverCard,\n  HoverCardContent,\n  HoverCardTrigger\n} from \"@glinui/ui\"\n\nexport function HoverCardLinkExample() {\n  return (\n    <div className=\"mx-auto w-full max-w-md text-sm leading-6\">\n      See the{\" \"}\n      <HoverCard openDelay={100} closeDelay={80}>\n        <HoverCardTrigger asChild><a href=\"#\" className=\"font-medium underline decoration-dotted underline-offset-4\">pricing page</a></HoverCardTrigger>\n        <HoverCardContent className=\"w-72\" size=\"sm\">\n          <p className=\"text-sm font-medium\">Pricing</p>\n          <p className=\"mt-1 text-xs text-[var(--color-muted)]\">Free for individuals. Team plans start at $20 per seat each month.</p>\n        </HoverCardContent>\n      </HoverCard>{\" \"}\n      for plan details.\n    </div>\n  )\n}\n",
  "TooltipToolbarHero": "\"use client\"\n\nimport { Image, Link as LinkIcon, TextB, TextItalic, TextUnderline } from \"@phosphor-icons/react\"\nimport {\n  Button,\n  Kbd,\n  Text,\n  Tooltip,\n  TooltipContent,\n  TooltipProvider,\n  TooltipTrigger\n} from \"@glinui/ui\"\n\nconst CARD = \"mx-auto w-full rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\"\n\nexport function TooltipToolbarHero() {\n  const tools = [\n    { icon: TextB, label: \"Bold\", keys: \"Ctrl B\" },\n    { icon: TextItalic, label: \"Italic\", keys: \"Ctrl I\" },\n    { icon: TextUnderline, label: \"Underline\", keys: \"Ctrl U\" },\n    { icon: LinkIcon, label: \"Insert link\", keys: \"Ctrl K\" },\n    { icon: Image, label: \"Insert image\", keys: \"Ctrl Shift I\" }\n  ]\n  return (\n    <TooltipProvider delayDuration={200}>\n      <div className={`${CARD} max-w-md pt-14`}>\n        <div role=\"toolbar\" aria-label=\"Text formatting\" className=\"flex flex-wrap items-center gap-1 rounded-xl border border-[var(--line-soft)] p-1\">\n          {tools.map(({ icon: Icon, label, keys }, index) => (\n            <Tooltip key={label} defaultOpen={index === 1}>\n              <TooltipTrigger asChild>\n                <Button size=\"icon\" variant=\"ghost\" aria-label={label}><Icon aria-hidden=\"true\" /></Button>\n              </TooltipTrigger>\n              <TooltipContent side=\"top\">{label} <Kbd size=\"sm\">{keys}</Kbd></TooltipContent>\n            </Tooltip>\n          ))}\n        </div>\n        <p className=\"mt-4 text-sm text-[var(--color-muted)]\">Hover or focus a button to see its name and shortcut.</p>\n      </div>\n    </TooltipProvider>\n  )\n}\n",
  "TooltipSidesExample": "\"use client\"\n\nimport { DownloadSimple } from \"@phosphor-icons/react\"\nimport {\n  Button,\n  Tooltip,\n  TooltipContent,\n  TooltipProvider,\n  TooltipTrigger\n} from \"@glinui/ui\"\n\nexport function TooltipSidesExample() {\n  return (\n    <TooltipProvider delayDuration={100}>\n      <div className=\"mx-auto flex flex-wrap items-center justify-center gap-3 py-8\">\n        {([\"top\", \"right\", \"bottom\", \"left\"] as const).map((side) => (\n          <Tooltip key={side}>\n            <TooltipTrigger asChild><Button variant=\"outline\" size=\"sm\">{side}</Button></TooltipTrigger>\n            <TooltipContent side={side}>{`Opens on the ${side}`}</TooltipContent>\n          </Tooltip>\n        ))}\n        <Tooltip>\n          <TooltipTrigger asChild><Button size=\"sm\" disabled aria-label=\"Export, unavailable\"><DownloadSimple aria-hidden=\"true\" />Export</Button></TooltipTrigger>\n          <TooltipContent>Export is unavailable on the free plan</TooltipContent>\n        </Tooltip>\n      </div>\n    </TooltipProvider>\n  )\n}\n",
  "DropdownAccountHero": "\"use client\"\n\nimport { CreditCard, Cube, GearSix, Lifebuoy, PencilSimple, SignOut } from \"@phosphor-icons/react\"\nimport {\n  Avatar,\n  Badge,\n  Button,\n  DropdownMenu,\n  DropdownMenuContent,\n  DropdownMenuItem,\n  DropdownMenuLabel,\n  DropdownMenuSeparator,\n  DropdownMenuShortcut,\n  DropdownMenuTrigger\n} from \"@glinui/ui\"\n\nexport function DropdownAccountHero() {\n  return (\n    <div className=\"mx-auto min-h-96 w-full max-w-lg\">\n      <div className=\"flex items-center justify-between gap-3 rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] px-4 py-2.5 [box-shadow:var(--elev-1)]\">\n        <span className=\"flex items-center gap-2 text-sm font-semibold\"><Cube aria-hidden=\"true\" className=\"size-4\" />Lumen</span>\n        <DropdownMenu defaultOpen modal={false}>\n          <DropdownMenuTrigger asChild>\n            <Button variant=\"ghost\" className=\"h-auto gap-2 px-2 py-1\" aria-label=\"Account menu\">\n              <Avatar size=\"sm\" fallback=\"AK\" alt=\"\" status=\"online\" />\n              <span className=\"hidden text-sm font-medium sm:inline\">Ava Kim</span>\n            </Button>\n          </DropdownMenuTrigger>\n          <DropdownMenuContent align=\"end\" className=\"w-64\">\n            <DropdownMenuLabel className=\"flex items-center justify-between gap-2\">\n              <span className=\"grid\"><span className=\"text-sm font-medium\">Ava Kim</span><span className=\"text-xs font-normal text-[var(--color-muted)]\">ava@lumen.test</span></span>\n              <Badge size=\"sm\" tone=\"accent\">Pro</Badge>\n            </DropdownMenuLabel>\n            <DropdownMenuSeparator />\n              <DropdownMenuItem><PencilSimple aria-hidden=\"true\" className=\"size-4\" />Profile<DropdownMenuShortcut>Ctrl P</DropdownMenuShortcut></DropdownMenuItem>\n              <DropdownMenuItem><CreditCard aria-hidden=\"true\" className=\"size-4\" />Billing<DropdownMenuShortcut>Ctrl B</DropdownMenuShortcut></DropdownMenuItem>\n              <DropdownMenuItem><GearSix aria-hidden=\"true\" className=\"size-4\" />Settings<DropdownMenuShortcut>Ctrl ,</DropdownMenuShortcut></DropdownMenuItem>\n            <DropdownMenuSeparator />\n            <DropdownMenuItem><Lifebuoy aria-hidden=\"true\" className=\"size-4\" />Support</DropdownMenuItem>\n            <DropdownMenuSeparator />\n            <DropdownMenuItem className=\"text-[var(--tone-danger-text)]\"><SignOut aria-hidden=\"true\" className=\"size-4\" />Sign out<DropdownMenuShortcut>Shift Q</DropdownMenuShortcut></DropdownMenuItem>\n          </DropdownMenuContent>\n        </DropdownMenu>\n      </div>\n    </div>\n  )\n}\n",
  "DropdownRowActionsExample": "\"use client\"\n\nimport { BookmarkSimple, Copy, DownloadSimple, FileText, Trash } from \"@phosphor-icons/react\"\nimport {\n  Button,\n  DropdownMenu,\n  DropdownMenuContent,\n  DropdownMenuItem,\n  DropdownMenuSeparator,\n  DropdownMenuTrigger,\n  IconFrame\n} from \"@glinui/ui\"\n\nconst CARD = \"mx-auto w-full rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\"\n\nexport function DropdownRowActionsExample() {\n  return (\n    <div className={`${CARD} max-w-md`}>\n      <div className=\"flex items-center gap-3\">\n        <IconFrame size=\"sm\"><FileText aria-hidden=\"true\" /></IconFrame>\n        <span className=\"grid min-w-0 flex-1 text-sm\"><span className=\"font-medium\">Vendor agreement.pdf</span><span className=\"text-xs text-[var(--color-muted)]\">2.4 MB, edited yesterday</span></span>\n        <DropdownMenu>\n          <DropdownMenuTrigger asChild><Button size=\"icon\" variant=\"ghost\" aria-label=\"File actions\">...</Button></DropdownMenuTrigger>\n          <DropdownMenuContent align=\"end\">\n            <DropdownMenuItem><DownloadSimple aria-hidden=\"true\" className=\"size-4\" />Download</DropdownMenuItem>\n            <DropdownMenuItem><Copy aria-hidden=\"true\" className=\"size-4\" />Duplicate</DropdownMenuItem>\n            <DropdownMenuItem><BookmarkSimple aria-hidden=\"true\" className=\"size-4\" />Add to favorites</DropdownMenuItem>\n            <DropdownMenuSeparator />\n            <DropdownMenuItem className=\"text-[var(--tone-danger-text)]\"><Trash aria-hidden=\"true\" className=\"size-4\" />Delete</DropdownMenuItem>\n          </DropdownMenuContent>\n        </DropdownMenu>\n      </div>\n    </div>\n  )\n}\n",
  "ContextFilesHero": "\"use client\"\n\nimport { FileText, FolderSimple, Image } from \"@phosphor-icons/react\"\nimport {\n  Badge,\n  ContextMenu,\n  ContextMenuCheckboxItem,\n  ContextMenuContent,\n  ContextMenuItem,\n  ContextMenuLabel,\n  ContextMenuSeparator,\n  ContextMenuShortcut,\n  ContextMenuSub,\n  ContextMenuSubContent,\n  ContextMenuSubTrigger,\n  ContextMenuTrigger,\n  Heading\n} from \"@glinui/ui\"\n\nconst FILES = [\n  { name: \"brand-guidelines.pdf\", size: \"4.2 MB\", icon: FileText },\n  { name: \"hero-banner.png\", size: \"1.1 MB\", icon: Image },\n  { name: \"Roadmap\", size: \"12 items\", icon: FolderSimple }\n]\n\nexport function ContextFilesHero() {\n  return (\n    <div className=\"mx-auto w-full max-w-md\">\n      <ContextMenu>\n        <ContextMenuTrigger className=\"block rounded-2xl border border-dashed border-[var(--color-border)] bg-[var(--surface-1)] p-4 [box-shadow:var(--elev-1)]\">\n          <div className=\"flex items-center justify-between gap-3 pb-3\">\n            <Heading level={3} size=\"sm\">Design assets</Heading>\n            <Badge size=\"sm\">Right click anywhere</Badge>\n          </div>\n          <ul className=\"grid divide-y divide-[var(--line-soft)]\">\n            {FILES.map(({ name, size, icon: Icon }) => (\n              <li key={name} className=\"flex items-center gap-3 py-2.5 text-sm\">\n                <Icon aria-hidden=\"true\" className=\"size-5 text-[var(--color-muted)]\" />\n                <span className=\"flex-1\">{name}</span>\n                <span className=\"text-xs text-[var(--color-muted)]\">{size}</span>\n              </li>\n            ))}\n          </ul>\n          <p className=\"pt-3 text-xs text-[var(--color-muted)]\">On touch screens, press and hold. On a keyboard, use Shift F10.</p>\n        </ContextMenuTrigger>\n        <ContextMenuContent className=\"w-60\">\n          <ContextMenuLabel>brand-guidelines.pdf</ContextMenuLabel>\n          <ContextMenuItem>Open <ContextMenuShortcut>Enter</ContextMenuShortcut></ContextMenuItem>\n          <ContextMenuItem>Rename <ContextMenuShortcut>F2</ContextMenuShortcut></ContextMenuItem>\n          <ContextMenuSub>\n            <ContextMenuSubTrigger>Move to</ContextMenuSubTrigger>\n            <ContextMenuSubContent>\n              <ContextMenuItem>Roadmap</ContextMenuItem>\n              <ContextMenuItem>Archive</ContextMenuItem>\n            </ContextMenuSubContent>\n          </ContextMenuSub>\n          <ContextMenuSeparator />\n          <ContextMenuCheckboxItem checked>Pin to top</ContextMenuCheckboxItem>\n          <ContextMenuSeparator />\n          <ContextMenuItem className=\"text-[var(--tone-danger-text)]\">Delete <ContextMenuShortcut>Del</ContextMenuShortcut></ContextMenuItem>\n        </ContextMenuContent>\n      </ContextMenu>\n    </div>\n  )\n}\n",
  "ContextCanvasExample": "\"use client\"\n\nimport { Globe, Plus } from \"@phosphor-icons/react\"\nimport {\n  ContextMenu,\n  ContextMenuCheckboxItem,\n  ContextMenuContent,\n  ContextMenuItem,\n  ContextMenuSeparator,\n  ContextMenuShortcut,\n  ContextMenuTrigger\n} from \"@glinui/ui\"\n\nexport function ContextCanvasExample() {\n  return (\n    <div className=\"mx-auto w-full max-w-md\">\n      <ContextMenu>\n        <ContextMenuTrigger className=\"flex h-40 items-center justify-center rounded-2xl border border-dashed border-[var(--color-border)] bg-[var(--surface-1)] text-sm text-[var(--color-muted)]\">\n          Right click the canvas\n        </ContextMenuTrigger>\n        <ContextMenuContent className=\"w-56\">\n          <ContextMenuItem><Plus aria-hidden=\"true\" className=\"size-4\" />New frame <ContextMenuShortcut>F</ContextMenuShortcut></ContextMenuItem>\n          <ContextMenuItem><Globe aria-hidden=\"true\" className=\"size-4\" />Paste here <ContextMenuShortcut>Ctrl V</ContextMenuShortcut></ContextMenuItem>\n          <ContextMenuSeparator />\n          <ContextMenuCheckboxItem checked>Show grid</ContextMenuCheckboxItem>\n          <ContextMenuCheckboxItem>Snap to objects</ContextMenuCheckboxItem>\n        </ContextMenuContent>\n      </ContextMenu>\n    </div>\n  )\n}\n",
  "CommandPaletteHero": "\"use client\"\n\nimport { CreditCard, FileText, FolderSimple, GearSix, MagnifyingGlass, Plus, UserPlus } from \"@phosphor-icons/react\"\nimport {\n  Command,\n  CommandEmpty,\n  CommandGroup,\n  CommandInput,\n  CommandItem,\n  CommandList,\n  CommandSeparator,\n  CommandShortcut,\n  Kbd\n} from \"@glinui/ui\"\n\nexport function CommandPaletteHero() {\n  return (\n    <div className=\"mx-auto w-full max-w-lg\">\n      <Command className=\"rounded-2xl border border-[var(--line-soft)] [box-shadow:var(--elev-2)]\">\n        <CommandInput placeholder=\"Search pages, people and commands\" />\n        <CommandList className=\"max-h-72\">\n          <CommandEmpty>No results for that search.</CommandEmpty>\n          <CommandGroup heading=\"Recent\">\n            <CommandItem><FileText aria-hidden=\"true\" className=\"size-4\" />Q4 roadmap</CommandItem>\n            <CommandItem><FolderSimple aria-hidden=\"true\" className=\"size-4\" />Brand assets</CommandItem>\n          </CommandGroup>\n          <CommandSeparator />\n          <CommandGroup heading=\"Suggestions\">\n            <CommandItem><Plus aria-hidden=\"true\" className=\"size-4\" />New document<CommandShortcut>Ctrl N</CommandShortcut></CommandItem>\n            <CommandItem><UserPlus aria-hidden=\"true\" className=\"size-4\" />Invite teammate<CommandShortcut>Ctrl I</CommandShortcut></CommandItem>\n            <CommandItem><MagnifyingGlass aria-hidden=\"true\" className=\"size-4\" />Search workspace<CommandShortcut>Ctrl F</CommandShortcut></CommandItem>\n          </CommandGroup>\n          <CommandSeparator />\n          <CommandGroup heading=\"Settings\">\n            <CommandItem><GearSix aria-hidden=\"true\" className=\"size-4\" />Preferences<CommandShortcut>Ctrl ,</CommandShortcut></CommandItem>\n            <CommandItem><CreditCard aria-hidden=\"true\" className=\"size-4\" />Billing</CommandItem>\n          </CommandGroup>\n        </CommandList>\n        <div className=\"flex items-center justify-between gap-3 border-t border-[var(--line-soft)] px-3 py-2 text-xs text-[var(--color-muted)]\">\n          <span className=\"flex items-center gap-1\"><Kbd size=\"sm\">Up</Kbd><Kbd size=\"sm\">Down</Kbd> to move</span>\n          <span className=\"flex items-center gap-1\"><Kbd size=\"sm\">Enter</Kbd> to open</span>\n        </div>\n      </Command>\n    </div>\n  )\n}\n",
  "CommandUsersExample": "\"use client\"\n\nimport {\n  Avatar,\n  Command,\n  CommandEmpty,\n  CommandGroup,\n  CommandInput,\n  CommandItem,\n  CommandList,\n  CommandShortcut\n} from \"@glinui/ui\"\n\nexport function CommandUsersExample() {\n  const people = [\n    { name: \"Ava Kim\", role: \"Owner\", initials: \"AK\" },\n    { name: \"Jon Reyes\", role: \"Admin\", initials: \"JR\" },\n    { name: \"Sara Patel\", role: \"Editor\", initials: \"SP\" },\n    { name: \"Mia Chen\", role: \"Viewer\", initials: \"MC\" }\n  ]\n  return (\n    <div className=\"mx-auto w-full max-w-sm\">\n      <Command className=\"rounded-2xl border border-[var(--line-soft)]\">\n        <CommandInput placeholder=\"Assign to...\" defaultValue=\"a\" />\n        <CommandList>\n          <CommandEmpty>Nobody matches that name.</CommandEmpty>\n          <CommandGroup heading=\"People\">\n            {people.map((person) => (\n              <CommandItem key={person.name} value={person.name}>\n                <Avatar size=\"xs\" fallback={person.initials} alt=\"\" />\n                {person.name}\n                <CommandShortcut>{person.role}</CommandShortcut>\n              </CommandItem>\n            ))}\n          </CommandGroup>\n        </CommandList>\n      </Command>\n    </div>\n  )\n}\n",
  "GlassNavbarHero": "\"use client\"\n\nimport { Lightning } from \"@phosphor-icons/react\"\nimport {\n  Avatar,\n  Badge,\n  GlassNavbar,\n  Heading,\n  Text\n} from \"@glinui/ui\"\n\nconst FEED = [\n  { id: \"a\", title: \"Q3 revenue is up 12 percent\", meta: \"Finance, 2 hours ago\" },\n  { id: \"b\", title: \"Checkout latency back under 300 ms\", meta: \"Platform, yesterday\" },\n  { id: \"c\", title: \"Three teams adopted the new onboarding flow\", meta: \"Product, Monday\" },\n  { id: \"d\", title: \"Security review passed for the billing service\", meta: \"Security, last week\" }\n]\n\nexport function GlassNavbarHero() {\n  return (\n    <div\n      tabIndex={0}\n      aria-label=\"Dashboard preview, scrollable\"\n      className=\"mx-auto h-80 w-full max-w-3xl overflow-y-auto rounded-2xl border border-[var(--line-soft)] bg-[linear-gradient(135deg,#6366f1,#ec4899_55%,#f59e0b)] p-3\"\n    >\n      <GlassNavbar aria-label=\"Workspace\" className=\"rounded-xl px-4\">\n        <div className=\"flex h-14 items-center justify-between gap-3\">\n          <div className=\"flex items-center gap-2 font-semibold\">\n            <Lightning aria-hidden=\"true\" />\n            Lumen\n          </div>\n          <nav aria-label=\"Primary\" className=\"hidden items-center gap-5 text-sm sm:flex\">\n            <a href=\"#\" aria-current=\"page\" className=\"font-medium\">Overview</a>\n            <a href=\"#\" className=\"text-[var(--color-muted)]\">Reports</a>\n            <a href=\"#\" className=\"text-[var(--color-muted)]\">Team</a>\n          </nav>\n          <div className=\"flex items-center gap-2\">\n            <Badge tone=\"accent\" size=\"sm\">Pro</Badge>\n            <Avatar size=\"sm\" fallback=\"AK\" alt=\"\" />\n          </div>\n        </div>\n      </GlassNavbar>\n      <div className=\"mt-3 grid gap-3\">\n        {FEED.map((item) => (\n          <article key={item.id} className=\"rounded-xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-4\">\n            <Heading level={3} size=\"sm\">{item.title}</Heading>\n            <Text size=\"sm\" className=\"mt-1 text-[var(--color-muted)]\">{item.meta}</Text>\n          </article>\n        ))}\n      </div>\n    </div>\n  )\n}\n",
  "GlassDockHero": "\"use client\"\n\nimport { ChartLineUp, Chat, FolderSimple, House, UsersThree } from \"@phosphor-icons/react\"\nimport {\n  GlassDock,\n  Heading,\n  Text\n} from \"@glinui/ui\"\n\nexport function GlassDockHero() {\n  return (\n    <div className=\"mx-auto flex min-h-72 w-full max-w-2xl flex-col justify-between rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-4 [box-shadow:var(--elev-1)]\">\n      <div className=\"grid gap-1\">\n        <Heading level={3} size=\"sm\">Good morning, Ava</Heading>\n        <Text size=\"sm\" className=\"text-[var(--color-muted)]\">3 reviews waiting and a standup at 10:30.</Text>\n      </div>\n      <GlassDock\n        aria-label=\"Applications\"\n        className=\"mx-auto\"\n        items={[\n          { id: \"home\", icon: <House weight=\"fill\" />, label: \"Home\" },\n          { id: \"files\", icon: <FolderSimple weight=\"fill\" />, label: \"Files\" },\n          { id: \"chat\", icon: <Chat weight=\"fill\" />, label: \"Messages\" },\n          { id: \"team\", icon: <UsersThree weight=\"fill\" />, label: \"Team\" },\n          { id: \"stats\", icon: <ChartLineUp weight=\"fill\" />, label: \"Analytics\" }\n        ]}\n      />\n    </div>\n  )\n}\n",
  "GlassBreadcrumbHero": "\"use client\"\n\nimport {\n  Button,\n  GlassBreadcrumb,\n  Heading,\n  Text\n} from \"@glinui/ui\"\n\nexport function GlassBreadcrumbHero() {\n  return (\n    <div className=\"mx-auto grid min-h-56 w-full max-w-2xl content-start gap-4 rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\">\n      <GlassBreadcrumb\n        aria-label=\"Project location\"\n        items={[\n          { id: \"ws\", label: \"Workspace\", href: \"#\" },\n          { id: \"proj\", label: \"Website redesign\", href: \"#\" },\n          { id: \"files\", label: \"Assets\", href: \"#\" },\n          { id: \"img\", label: \"Hero images\", href: \"#\" },\n          { id: \"cur\", label: \"launch-banner.png\" }\n        ]}\n        maxItems={4}\n      />\n      <div className=\"flex items-center justify-between gap-3\">\n        <div>\n          <Heading level={3} size=\"sm\">launch-banner.png</Heading>\n          <Text size=\"sm\" className=\"text-[var(--color-muted)]\">2.4 MB, edited 3 hours ago by Jon Reyes</Text>\n        </div>\n        <Button size=\"sm\" variant=\"outline\">Download</Button>\n      </div>\n    </div>\n  )\n}\n",
  "MorphingTabsHero": "\"use client\"\n\nimport * as React from \"react\"\nimport {\n  Badge,\n  Heading,\n  MorphingTabs,\n  Text\n} from \"@glinui/ui\"\n\nconst REPORT_PANELS: Record<string, { title: string; text: string; badge: string }> = {\n  overview: { title: \"Revenue this month\", text: \"$48,200 across 312 paid invoices, up 8 percent on last month.\", badge: \"+8%\" },\n  customers: { title: \"Active customers\", text: \"1,284 accounts used the product at least once in the last 30 days.\", badge: \"1,284\" },\n  invoices: { title: \"Open invoices\", text: \"17 invoices are waiting on payment, 4 of them past their due date.\", badge: \"17\" },\n  settings: { title: \"Billing settings\", text: \"Net 30 terms, USD, invoices sent from billing@lumen.test.\", badge: \"Net 30\" }\n}\n\nexport function MorphingTabsHero() {\n  const [active, setActive] = React.useState(\"overview\")\n  const panel = REPORT_PANELS[active]\n  return (\n    <div className=\"mx-auto grid w-full max-w-xl gap-4 rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\">\n      <MorphingTabs\n        aria-label=\"Billing sections\"\n        activeId={active}\n        onTabChange={setActive}\n        items={[\n          { id: \"overview\", label: \"Overview\" },\n          { id: \"customers\", label: \"Customers\" },\n          { id: \"invoices\", label: \"Invoices\" },\n          { id: \"settings\", label: \"Settings\" }\n        ]}\n      />\n      <div role=\"region\" aria-live=\"polite\" className=\"rounded-xl border border-[var(--line-soft)] p-4\">\n        <div className=\"flex items-center justify-between gap-3\">\n          <Heading level={3} size=\"sm\">{panel.title}</Heading>\n          <Badge tone=\"accent\" size=\"sm\">{panel.badge}</Badge>\n        </div>\n        <Text size=\"sm\" className=\"mt-2 text-[var(--color-muted)]\">{panel.text}</Text>\n      </div>\n    </div>\n  )\n}\n",
  "FloatingPanelProductHero": "\"use client\"\n\nimport {\n  Avatar,\n  Badge,\n  Button,\n  FloatingPanel,\n  Heading,\n  Text\n} from \"@glinui/ui\"\n\nexport function FloatingPanelProductHero() {\n  return (\n    <div className=\"relative mx-auto min-h-72 w-full max-w-2xl overflow-hidden rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\">\n      <Heading level={3} size=\"sm\">Homepage draft</Heading>\n      <Text size=\"sm\" className=\"mt-1 max-w-sm text-[var(--color-muted)]\">\n        Drag the inspector anywhere on the canvas. It keeps its place while you edit the page.\n      </Text>\n      <div className=\"mt-4 grid max-w-sm gap-2\" aria-hidden=\"true\">\n        <div className=\"h-3 rounded-full bg-[var(--surface-3)]\" />\n        <div className=\"h-3 w-4/5 rounded-full bg-[var(--surface-3)]\" />\n        <div className=\"h-3 w-3/5 rounded-full bg-[var(--surface-3)]\" />\n      </div>\n      <FloatingPanel closable draggable defaultX={300} defaultY={36} width={240} aria-label=\"Inspector\">\n        <div className=\"grid gap-3 p-4\">\n          <Heading level={4} size=\"sm\">Inspector</Heading>\n          <div className=\"flex items-center justify-between text-sm\">\n            <span>Status</span>\n            <Badge tone=\"success\" size=\"sm\">Published</Badge>\n          </div>\n          <div className=\"flex items-center justify-between text-sm\">\n            <span>Owner</span>\n            <Avatar size=\"sm\" fallback=\"AK\" alt=\"Ava Kim\" />\n          </div>\n          <Button size=\"sm\">Publish changes</Button>\n        </div>\n      </FloatingPanel>\n    </div>\n  )\n}\n",
  "ToastSaveHero": "\"use client\"\n\nimport * as React from \"react\"\nimport {\n  Avatar,\n  Button,\n  Heading,\n  Text,\n  Toaster,\n  toast\n} from \"@glinui/ui\"\n\nexport function ToastSaveHero() {\n  const [saves, setSaves] = React.useState(0)\n  return (\n    <div className=\"mx-auto grid w-full max-w-md gap-4 rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\">\n      <Toaster position=\"bottom-right\" />\n      <div>\n        <Heading level={3} size=\"sm\">Profile</Heading>\n        <Text size=\"sm\" className=\"mt-1 text-[var(--color-muted)]\">Changes to your display name and photo apply across the workspace.</Text>\n      </div>\n      <div className=\"flex items-center gap-3\">\n        <Avatar size=\"md\" fallback=\"AK\" alt=\"\" />\n        <div className=\"grid text-sm\">\n          <span className=\"font-medium\">Ava Kim</span>\n          <span className=\"text-[var(--color-muted)]\">{saves} saves this session</span>\n        </div>\n      </div>\n      <div className=\"flex justify-end\">\n        <Button\n          onClick={() => {\n            setSaves((n) => n + 1)\n            toast.success(\"Profile saved\", {\n              description: \"Your changes are live for everyone in Lumen.\",\n              action: {\n                label: \"Undo\",\n                onClick: () => {\n                  setSaves((n) => Math.max(0, n - 1))\n                  toast(\"Changes reverted\")\n                }\n              }\n            })\n          }}\n        >\n          Save changes\n        </Button>\n      </div>\n    </div>\n  )\n}\n",
  "ToastStackHero": "\"use client\"\n\nimport { Trash, Warning, X } from \"@phosphor-icons/react\"\nimport {\n  Button,\n  Heading,\n  Text,\n  Toaster,\n  toast\n} from \"@glinui/ui\"\n\nexport function ToastStackHero() {\n  return (\n    <div className=\"mx-auto grid w-full max-w-md gap-4 rounded-2xl border border-[var(--line-soft)] bg-[var(--surface-1)] p-5 [box-shadow:var(--elev-1)]\">\n      <Toaster position=\"bottom-right\" closeButton visibleToasts={4} />\n      <div>\n        <Heading level={3} size=\"sm\">Notification variants</Heading>\n        <Text size=\"sm\" className=\"mt-1 text-[var(--color-muted)]\">Fire a few in a row to see them stack and collapse.</Text>\n      </div>\n      <div className=\"flex flex-wrap gap-2\">\n        <Button size=\"sm\" onClick={() => toast.success(\"Deploy finished\", { description: \"lumen-web is live on production.\" })}>Success</Button>\n        <Button size=\"sm\" variant=\"outline\" onClick={() => toast.warning(\"Storage almost full\", { description: \"You have used 92 percent of your plan.\" })}>\n          <Warning aria-hidden=\"true\" />\n          Warning\n        </Button>\n        <Button size=\"sm\" variant=\"outline\" onClick={() => toast.error(\"Payment failed\", { description: \"Your card ending 4242 was declined.\" })}>\n          <X aria-hidden=\"true\" />\n          Error\n        </Button>\n        <Button size=\"sm\" variant=\"outline\" onClick={() => toast(\"File deleted\", { description: \"launch-banner.png moved to trash.\", action: { label: \"Undo\", onClick: () => toast.success(\"Restored\") } })}>\n          <Trash aria-hidden=\"true\" />\n          With undo\n        </Button>\n      </div>\n    </div>\n  )\n}\n"
}
